const LOCAL_GUESS_LOG_PREFIX = "hunt.puzzles.guesses.v1:";

const canUseStorage = () =>
  typeof window !== "undefined" && typeof window.localStorage !== "undefined";

export const getLocalGuessLogKey = (slug: string) =>
  `${LOCAL_GUESS_LOG_PREFIX}${slug}`;

export const clearLocalGuessLogs = (slugs: string[]): boolean => {
  if (!canUseStorage()) return false;
  if (!slugs.length) return false;
  let changed = false;
  slugs.forEach((slug) => {
    if (!slug) return;
    const key = getLocalGuessLogKey(slug);
    if (window.localStorage.getItem(key) !== null) {
      changed = true;
    }
    window.localStorage.removeItem(key);
  });
  return changed;
};
