import { ALPHABET_LETTER_TO_SLUG, isAlphabetSlug } from "@hunt/alpha-round";
import { type TeamHuntState } from "@hunt/public-client";
import { PUZZLES, getPuzzleTitle } from "@hunt/puzzles";
import React, { useMemo } from "react";
import { hydrateRoot } from "react-dom/client";
import AllPuzzlesList from "../components/AllPuzzlesList";
import { useLandOfNoNameLettersState } from "../components/alphabet/landOfNoNameLocalState";
import {
  applySolvedMapToAllPuzzlesState,
  useSolvedPuzzlesState,
} from "../components/puzzleSolveLocalState";
import { IS_STATIC_SITE } from "../utils/staticSite";
import { ErrataDataProvider } from "./ErrataProvider";
import { type AllPuzzlesState } from "./all_puzzles_types";
import useDataset from "./useDataset";

const ALL_ALPHABET_LETTERS = Object.keys(ALPHABET_LETTER_TO_SLUG);

const applyAlphabetLettersToAllPuzzlesState = (
  state: AllPuzzlesState,
  teamState: TeamHuntState,
): AllPuzzlesState => {
  if (state.rounds.length === 0) {
    return state;
  }
  let changed = false;
  const rounds = state.rounds.map((round) => {
    const puzzles = round.puzzles.map((puzzle) => {
      if (!isAlphabetSlug(puzzle.slug)) {
        return puzzle;
      }
      const puzzleDef = PUZZLES[puzzle.slug];
      if (!puzzleDef) {
        return puzzle;
      }
      const nextTitle = getPuzzleTitle(puzzleDef, teamState);
      if (nextTitle === puzzle.title) {
        return puzzle;
      }
      changed = true;
      return { ...puzzle, title: nextTitle };
    });
    if (puzzles === round.puzzles) {
      return round;
    }
    return { ...round, puzzles };
  });
  return changed ? { ...state, rounds } : state;
};

const AllPuzzlesManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: AllPuzzlesState;
  initialTeamState: TeamHuntState;
}) => {
  const state = useDataset("all_puzzles", undefined, initialState);
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const { solvedMap } = useSolvedPuzzlesState();
  const { solvedLetters, showAllLetters } = useLandOfNoNameLettersState();
  const availableLetters = useMemo(() => {
    if (!IS_STATIC_SITE) {
      return [];
    }
    if (showAllLetters) {
      return ALL_ALPHABET_LETTERS;
    }
    return solvedLetters.map((letter) => letter.toUpperCase());
  }, [showAllLetters, solvedLetters]);
  const teamStateWithOverride = useMemo(
    () =>
      ({
        ...teamState,
        alpha_available_letters_override: availableLetters,
      }) as TeamHuntState & { alpha_available_letters_override: string[] },
    [availableLetters, teamState],
  );
  const mergedState = useMemo(() => {
    if (!IS_STATIC_SITE) return state;
    const withSolved = applySolvedMapToAllPuzzlesState(state, solvedMap);
    return applyAlphabetLettersToAllPuzzlesState(
      withSolved,
      teamStateWithOverride,
    );
  }, [solvedMap, state, teamStateWithOverride]);

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <AllPuzzlesList state={mergedState} teamState={teamState} />
    </ErrataDataProvider>
  );
};

const allPuzzlesElem = document.getElementById("all-puzzles-root");
if (allPuzzlesElem) {
  const initialAllPuzzlesState = (
    window as unknown as { initialAllPuzzlesState: AllPuzzlesState }
  ).initialAllPuzzlesState;
  const teamState = (window as unknown as { initialTeamState: TeamHuntState })
    .initialTeamState;
  hydrateRoot(
    allPuzzlesElem,
    <AllPuzzlesManager
      initialState={initialAllPuzzlesState}
      initialTeamState={teamState}
    />,
  );
} else {
  console.error(
    "Couldn't mount AllPuzzlesManager because #all-puzzles-root was nowhere to be found",
  );
}
